int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n, m;
    while (cin >> n >> m) {
        if (m == 0 || m == 1) {
            cout << 1 << '\n';
        } else if (n == m) {
            cout << 0 << '\n';
        } else if (n / 2 > m) {
            cout << m << '\n';
        } else {
            cout << n - m << '\n';
        }
    }

    return 0;
}

